mapper.select:
select d.detail_id , d.status as detail_state, d.todo_id , i.business_code, i.business_id, i.title, i.business_content as content, i.callback_link, i.create_time as submit_time from todo_item_detail d LEFT JOIN todo_item i on i.todo_id = d.todo_id where 1=1
and d.user_id = #{userId}
and d.status = #{status}

select count(distinct d.business_id) as value,d.user_id,u.nick_name as name,COALESCE(sd.dept_name,'其它') as
dept_name
from todo_item_detail d
left join sys_user u on u.user_id = d.user_id
left join sys_dept sd on sd.dept_id = d.dept_id
left join todo_item i on d.todo_id = i.todo_id
where 1=1

    and d.user_id = #{userId}


    and d.dept_id = #{deptId}
    and u.dept_id = #{deptId}


    and d.status = #{status}


    and i.state = #{itemState}


    and d.create_time >= #{startTime}


    and d.create_time <= #{endTime}


    and d.type = #{type}

group by d.user_id,u.nick_name,sd.dept_name
ORDER BY VALUE DESC

select count(DISTINCT d.business_id) as value,COALESCE(d.type,'其它') as name
from todo_item_detail d
where 1=1

    and d.user_id = #{userId}


    and d.status = #{status}


    and d.create_time >= #{startTime}


    and d.create_time <= #{endTime}

GROUP BY d.type

select count(DISTINCT business_id) as value,status as code
from todo_item_detail
where 1=1

    and user_id = #{userId}


    and create_time >= #{startTime}


    and create_time <= #{endTime}


    and type = #{type}

GROUP BY status

select count(DISTINCT d.business_id) as value ,COALESCE(d.type,'其它') as type,COALESCE(d.dept_id,'其它') as code ,COALESCE(t.dept_name,'其它') as name
from todo_item_detail d
where 1=1

    and d.status = #{status}


    and create_time >= #{startTime}


    and create_time <= #{endTime}


    and i.state = #{itemState}

left join sys_dept t on t.dept_id = d.dept_id
group by d.dept_id,d.type,t.dept_name;

select count(distinct d.business_id) as value,d.user_id as code,u.nick_name as name,COALESCE(sd.dept_name,'其它')
as dept_name,COALESCE(i.type,'其它') as type
from todo_item_detail d
left join sys_user u on u.user_id = d.user_id
left join sys_dept sd on sd.dept_id = d.dept_id
left join todo_item i on d.todo_id = i.todo_id
where 1=1

    and d.user_id = #{userId}


    and d.status = #{status}


    and i.state = #{itemState}


    and d.create_time >= #{startTime}


    and d.create_time <= #{endTime}


    and d.type = #{type}

group by d.user_id,i.type,u.nick_name,sd.dept_name
